//----W-Craft WebSquare 변환 확인: include----//
scwin.contnId;
scwin.objTpCd;
scwin.vCurDate;
scwin.gLdMktTp = js_market;
scwin.vScrenID = "ULDMGT42045.gfm";

// scwin.onpageload, scwin.onpageunload 함수
scwin.onpageload = function() {
};

scwin.onpageunload = function() {
};

// WebSquare 컴포넌트 이벤트 함수
scwin.btn_save_onclick = function() {
    if (scwin.contnId === "input") {
        scwin.save();
    } else {
        scwin.update();
    }
};

scwin.trs_Save_OnSuccess = async function() {
    alert($c.data.getMessage("MSG-A001", "도움말등록"));
    await $c.win.closePopup();
};

scwin.trs_Save_OnFail = function() {
    alert($c.data.getMessage("MSG-A002", "도움말등록"));
    // TODO Stage2: trs 객체 제거됨 - executeDynamic 오류 메시지 처리 재검토
    //alert(trs_Save.ErrorMsg);
    //alert(dts_C_All.ErrorMsg);

};

scwin.trs_Update_OnSuccess = async function() {
    alert($c.data.getMessage("MSG-A001", "도움말수정"));
    await $c.win.closePopup();
};

scwin.trs_Update_OnFail = function() {
    alert($c.data.getMessage("MSG-A002", "도움말수정"));
    // TODO Stage2: trs 객체 제거됨 - executeDynamic 오류 메시지 처리 재검토
    //alert(trs_Update.ErrorMsg);
    //alert(dts_C_All.ErrorMsg);

};

scwin.trs_Delete_OnSuccess = async function() {
    alert($c.data.getMessage("MSG-A001", "도움말삭제"));
    await $c.win.closePopup();
};

scwin.trs_Delete_OnFail = function() {
    alert($c.data.getMessage("MSG-A002", "도움말삭제"));
    // TODO Stage2: trs 객체 제거됨 - executeDynamic 오류 메시지 처리 재검토
    //alert(trs_Delete.ErrorMsg);
    //alert(dts_C_All.ErrorMsg);

};

scwin.inf_find_OnClick = function() {
    const filenm = file_name.value;
    dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.Value);
    file_name.setValue(inf_find.Value);
    if (inf_find.Value === "") {
        file_name.setValue(filenm);
    }
};

scwin.btn_cancel_onclick = async function() {
    await $c.win.closePopup();
};

//----W-Craft WebSquare 변환 확인: Filter----//
scwin.topmenusearch_OnFilter = function(row) {
    f1 = topmenusearch.getCellData(row, "MENU_NM");
    if (f1.indexOf(cmb_QuickMenu_scren.getText()) !== -1) {
        return true;
    } else {
        return false;
    }
};

scwin.cmb_QuickMenu_scren_OnCloseUp = function() {
    const selval = cmb_QuickMenu_scren.getText();
    if (selval !== "화면명검색") {
        e = selval.split("_");
        if (e.length > 1) {
            cmb_QuickMenu_scren.setSelectedIndex(-1);
            ipt_scren_id.setValue(e[1].toString());
            ipt_scren_nm.setValue(e[0].toString());
        }
    }
};

scwin.cmb_QuickMenu_scren_OnKeyDown = function(keycode) {
    if (keycode === 13) {
        scwin.topmenusearchEnter();
    }
};

scwin.file_OnClick = function() {
    scwin.selectAttach();
};

scwin.btn_delete_onclick = function() {
    scwin.delete();
};

scwin.cb_system_gbn_onselchange = function() {
    scwin.listMenu();
};

scwin.checkbox_1_onclick = function() {
    if (checkbox_1.checked) {
        ipt_scren_id_2.show();
        cmb_QuickMenu_scren.hide();
        ipt_scren_nm.hide();
        ipt_scren_id.hide();
    } else {
        ipt_scren_id_2.hide();
        cmb_QuickMenu_scren.show();
        ipt_scren_nm.show();
        ipt_scren_id.show();
    }
};

// 일반 함수
scwin.singleRead = function() {
    //공지사항 개별조회

    //----W-Craft WebSquare 변환 확인: getContnId----//
    let getContnId = $c.frame.path("../").fn_getContnId;

    //----W-Craft WebSquare 변환 확인: getContnId----//
    let screnID = getContnId();

    //----W-Craft WebSquare 변환 확인: Post----//
    const sbmOptions = {
        id : "sbm_trs_Read",
        action : "/scren.do",
        ref : "dts_NoticeContentSingle,dts_fileList",
        target : "trs_Read=body.content",
        // TODO Stage2: 원본 submission에 submitdone 없음
        submitDoneHandler : scwin.sbm_trs_Read_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);
};

scwin.update = function() {
    //공지사항 수정

    if (confirm('위사항을 수정 하시겠습니까?')) {
        dts_NoticeContentSingle.setCellData(1, "NOTI_OBJ_SYS_TP_CD", $c.cp.valueOfIndex(cb_system_gbn, "VALUE", cb_system_gbn.getSelectedIndex()));
        let url1 = "/scren.do?method=modifyHelpContent" + "&SCREN_ID=" + scwin.vScrenID + "&V_SCREN_ID=" + scwin.contnId + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&FILE_NM=" + dts_fileList.getCellData(1, "filename");
        const sbmOptions = {
            id : "sbm_trs_Update",
            action : encodeURI(url1),
            ref : "dts_NoticeContentSingle,dts_fileList",
            target : "trs_Update=body.content",
            submitDoneHandler : scwin.trs_Update_OnSuccess,
            submitErrorHandler : scwin.trs_Update_OnFail,
            isProcessMsg : false
        };

        $c.sbm.executeDynamic(sbmOptions);
    }
};

scwin.save = function() {
    //공지사항 등록
    if (cb_system_gbn.getSelectedIndex() <= 0) {
        alert("시스템을 선택하세요");
        cb_system_gbn.focus();
        return;
    }
    if (checkbox_1.checked) {
        ipt_scren_id.setValue(ipt_scren_id_2.getValue());
    }
    if (ipt_scren_id.getValue() === '') {
        alert("화면을 선택하세요");
        cmb_QuickMenu_scren.focus();
        return;
    }
    if (txb_ATTACH_FILE_NM.getValue() === '') {
        alert("첨부파일을 선택하세요");
        file.focus();
        return;
    }
    let url1 = "/scren.do?method=helpNoticeContent" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&FILE_NM=" + dts_fileList.getCellData(1, "filename");
    //dts_noticeInfo.NameValue(1,"NOTI_OBJ_SYS_TP_CD") = cb_system_gbn.ValueOfIndex("VALUE", cb_system_gbn.Index);
    // TODO Stage2: 0-based 검토
    dts_noticeInfo.setCellData(1, "NOTI_OBJ_SYS_TP_CD", MxDataSet_code1.getCellData((cb_system_gbn.getSelectedIndex() + 1), "CD_VAL"));

    const sbmOptions = {
        id : "sbm_trs_Save",
        action : encodeURI(url1),
        ref : "dts_noticeInfo,dts_fileList",
        target : "trs_Save=body.content",
        submitDoneHandler : scwin.trs_Save_OnSuccess,
        submitErrorHandler : scwin.trs_Save_OnFail,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);
    dts_fileList.removeAll();
    dts_fileList.insertRow();
    txb_ATTACH_FILE_NM.setValue('');
};

scwin.delete = function() {
    //공지사항 삭제

    if (confirm('내용을 삭제 하시겠습니까?')) {

        //dts_NoticeDelete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        dts_NoticeDelete.insertRow();
        dts_NoticeDelete.setCellData(1, "CONTN_ID", scwin.contnId);
        dts_NoticeDelete.setCellData(1, "NOTI_OBJ_SYS_TP_CD", scwin.objTpCd);

        //----W-Craft WebSquare 변환 확인: getContnId----//
        let getContnId = $c.frame.path("../").fn_getContnId;

        //----W-Craft WebSquare 변환 확인: getContnId----//
        let screnID = getContnId();

        //----W-Craft WebSquare 변환 확인: Post----//
        const sbmOptions = {
            id : "sbm_trs_Delete",
            action : "/scren.do",
            ref : "dts_NoticeDelete",
            target : "trs_Delete=body.content",
            submitDoneHandler : scwin.trs_Delete_OnSuccess,
            submitErrorHandler : scwin.trs_Delete_OnFail,
            isProcessMsg : false
        };

        $c.sbm.executeDynamic(sbmOptions);
    }
};

scwin.setIrInfoHeader = function() {
    // CUD용 Header
    const sbmOptions = {
        id : "sbm_dts_noticeInfo",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_noticeInfo=body.content",
        // TODO Stage2: 원본 submission에 submitdone 없음
        submitDoneHandler : scwin.sbm_dts_noticeInfo_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


    dts_noticeInfo.insertRow();
};

//파일 다운로드
scwin.filedown = function(attach_seq) {
    location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&gubun=35";
};

scwin.checkMaxLength1 = function(obj, size, lbl) {
    let overLen = eval($c.str.getByteLength(obj.value) - size);
    if (overLen > 0) {
        alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};

scwin.code1Sync = function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_code1",
        action : "/scren.do",
        ref : "",
        target : "MxDataSet_code1=body.content",
        // TODO Stage2: 원본 submission에 submitdone 없음
        submitDoneHandler : scwin.sbm_MxDataSet_code1_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


};

scwin.checkMaxLength2 = function(obj, size, lbl) {
    let overLen = eval($c.str.getByteLength(obj.text) - size);
    if (overLen > 0) {
        alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};

scwin.selectAttach = function() {
    if (scwin.contnId !== "input") {
        dts_fileList.removeAll();
        //dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_fileList.insertRow();
    }
    if (file.Value === "") return;
    txb_ATTACH_FILE_NM.setValue(file.Value);
    dts_fileList.setCellData(1, "fileInfo", file.Value);
    dts_fileList.setCellData(1, "fileUrl", file.Value);
    dts_fileList.setCellData(1, "filename", file.Value);
};

//2017-02-13 KBoY FileSizeLimit 30MB		
scwin.canUploadFile = function() {
    const maxFileSize = 1024 * 1024 * 30; //30MB		

    //----W-Craft WebSquare 변환 확인: FileInfo----//
    const mySize = inf_find.FileInfo('size');
    if (mySize < maxFileSize) {
        return true;
    } else {
        return false;
    }
};

scwin.listMenu = function() {
    // TODO Stage2: 0-based 검토
    const cbSystemGbnValue = MxDataSet_code1.getCellData((cb_system_gbn.getSelectedIndex() + 1), "CD_VAL");
    const sbmOptions = {
        id : "sbm_dts_menu",
        action : "/topmenu.do",
        ref : "",
        target : "dts_menu=body.content",
        // TODO Stage2: 원본 submission에 submitdone 없음
        submitDoneHandler : scwin.sbm_dts_menu_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


    const sbmOptions2 = {
        id : "sbm_topmenusearch",
        action : "/topmenu.do",
        ref : "",
        target : "topmenusearch=body.content",
        // TODO Stage2: 원본 submission에 submitdone 없음
        submitDoneHandler : scwin.sbm_topmenusearch_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions2);


};

scwin.topmenusearchEnter = function() {
    // 2008-06-30
    //화면검색 엔터시

    // TODO Stage2: 필터 재구현 (Gauce UseFilter/Filter → WebSquare setColumnFilter 등)
    //topmenusearch.UseFilter = "true";
    //topmenusearch.Filter();

    //----W-Craft WebSquare 변환 확인: ResetData----//

    //----W-Craft WebSquare 변환 확인: Reset----//
    cmb_QuickMenu_scren.ResetData();
    cmb_QuickMenu_scren.setSelectedIndex(-1);
    cmb_QuickMenu_scren.trigger("onclick");
};

scwin.gform_onload = function() {
    ipt_scren_id_2.hide();
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");

    //----W-Craft WebSquare 변환 확인: getContnId----//
    getContnId = $c.frame.path("../").fn_getContnId;

    //----W-Craft WebSquare 변환 확인: getContnId----//
    scwin.contnId = getContnId();
    if (scwin.contnId !== "input") {
        scwin.singleRead();
        dts_fileList.insertRow();
        dts_fileList.setCellData(1, "fileInfo", dts_NoticeContentSingle.getCellData(1, "SAVE_FILE_NM"));
        txb_ATTACH_FILE_NM.setValue(dts_NoticeContentSingle.getCellData(1, "SAVE_FILE_NM"));
        const sbmOptions = {
            id : "sbm_MxDataSet_code1",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "MxDataSet_code1=body.content",
            // TODO Stage2: 원본 submission에 submitdone 없음
            submitDoneHandler : scwin.sbm_MxDataSet_code1_submitdone,
            isProcessMsg : false
        };

        $c.sbm.executeDynamic(sbmOptions);


        scwin.code1Sync();
        const cb_system_gbn_idx = $c.cp.getNameValueRow(MxDataSet_code1, "CD_VAL", dts_NoticeContentSingle.getCellData(1, "NOTI_OBJ_SYS_TP_CD"));
        //var cb_system_gbn_idx = cb_system_gbn.IndexOfColumn("value", dts_NoticeContentSingle.NameString(1,"NOTI_OBJ_SYS_TP_CD"));
        //cb_system_gbn.Index = cb_system_gbn_idx;
        cb_system_gbn.setSelectedIndex((cb_system_gbn_idx - 1));
        cmb_QuickMenu_scren.hide();
        cb_system_gbn.setDisabled(true);
        checkbox_1.hide();
    } else {
        cb_system_gbn.setDisabled(false);
        //dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_fileList.insertRow();
        scwin.setIrInfoHeader();
        btn_delete.hide();

        //메뉴리스트 조회
        topmenusearch.dataid = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=topmenu";

        //----W-Craft WebSquare 변환 확인: reset----//
        topmenusearch.reset(); //2008-06-30 추가

        dts_menu.dataid = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=topmenu";

        //----W-Craft WebSquare 변환 확인: reset----//
        dts_menu.reset();
        //fn_list_menu();	
        userName.setValue(js_emp_nm);
        //cb_system_gbn.ResetData(); 

        const sbmOptions = {
            id : "sbm_MxDataSet_code1",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "MxDataSet_code1=body.content",
            // TODO Stage2: 원본 submission에 submitdone 없음
            submitDoneHandler : scwin.sbm_MxDataSet_code1_submitdone,
            isProcessMsg : false
        };

        $c.sbm.executeDynamic(sbmOptions);


        scwin.code1Sync();
    }
    cmb_QuickMenu_scren.setSelectedIndex(-1);
};
